SELECT p.sku, p.path, p.brand, p.series, p.model, p.name, json_extract(p.properties,'$.color_family') AS color_family FROM products p WHERE p.brand='Helly Hansen' AND p.series LIKE '%Helly Hansen Softshell HH%' AND p.model='2NY-U3D' AND p.name LIKE '%Work Jacket%' AND json_extract(p.properties,'$.color_family')='Orange' LIMIT 10;
SELECT store_id, name, city FROM stores WHERE city='Vienna' ORDER BY store_id;
SELECT i.store_id, i.sku, i.available_today FROM inventory i JOIN stores s ON s.store_id=i.store_id WHERE s.city='Vienna' AND i.sku IN (SELECT sku FROM products WHERE brand='Helly Hansen' AND series LIKE '%Helly Hansen Softshell HH%' AND model='2NY-U3D' AND name LIKE '%Work Jacket%' AND json_extract(properties,'$.color_family')='Orange') ORDER BY i.store_id;

WITH target_store AS (
  SELECT store_id FROM stores WHERE city='Graz' AND store_name LIKE '%Jakomini%' LIMIT 1
),
hammerite AS (
  SELECT v.brand, v.series, v.model, v.product_sku, v.record_path, i.available_today_quantity
  FROM product_variants v
  LEFT JOIN store_inventory i ON i.product_sku=v.product_sku AND i.store_id=(SELECT store_id FROM target_store)
  WHERE v.brand='Hammerite' AND (v.model LIKE '%22B-SYZ%' OR v.model LIKE '%HAM 22B-SYZ%' OR v.series LIKE '%Quick Dry%')
)
SELECT * FROM hammerite ORDER BY model, product_sku LIMIT 100;
